50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	const BLOCK_SIZE = 3;
64	
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	const countByType = (items: Item[]): Map<string, number> => {
68	  const counts = new Map<string, number>();
69	
70	  for (const item of items) {
71	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
72	  }
73	
74	  return counts;
75	};
76	
77	const typeGroupBasePremiumOf = ([type, count]: [string, number]): number =>
78	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
79	
80	const policyBasePremiumOf = (items: Item[]): number =>
81	  [...countByType(items)].reduce(
82	    (sum, typeGroup) => sum + typeGroupBasePremiumOf(typeGroup),
83	    0,
84	  );
85	
86	const HIGH_ENCHANTMENT_THRESHOLD = 5;
87	
88	// An item surcharge hits every item the predicate accepts, charging its rate
89	// against that item's own base premium.
90	interface ItemSurcharge {
91	  appliesTo: (item: Item) => boolean;
92	  rate: number;
93	}
94	
95	const ITEM_SURCHARGES: ItemSurcharge[] = [
96	  { appliesTo: (item) => item.cursed === true, rate: 0.5 },
97	  {
98	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
99	    rate: 0.3,
100	  },
101	];
102	
103	const surchargeOf = (items: Item[], { appliesTo, rate }: ItemSurcharge): number =>
104	  items
105	    .filter(appliesTo)
106	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);
107	
108	// Item-specific modifiers apply to the affected item's own base premium.
109	const itemModifiersOf = (items: Item[]): number =>
110	  ITEM_SURCHARGES.reduce(
111	    (sum, surcharge) => sum + surchargeOf(items, surcharge),
112	    0,
113	  );
114	
115	const LOYALTY_DISCOUNT_RATE = 0.2;
116	
117	const LOYALTY_YEARS_THRESHOLD = 2;
118	
119	const isLoyal = (customer: Customer): boolean =>
120	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
121	
122	// Policy-wide modifiers apply to the policy base premium, so they are computed
123	// from the base alone — item-specific modifiers are not part of their base.
124	const policyModifiersOf = (policyBase: number, customer: Customer): number => {
125	  const loyaltyDiscount = isLoyal(customer) ? policyBase * LOYALTY_DISCOUNT_RATE : 0;
126	
127	  return policyBase * FIRST_INSURANCE_SURCHARGE_RATE - loyaltyDiscount;
128	};
129	
130	const quote = ({ items }: QuoteStep, customer: Customer): QuoteResult => {
131	  const policyBase = policyBasePremiumOf(items);
132	
133	  const premiumBeforeRounding =
134	    policyBase +
135	    itemModifiersOf(items) +
136	    policyModifiersOf(policyBase, customer) +
137	    PROCESSING_FEE;
138	
139	  return { premium: Math.ceil(premiumBeforeRounding) };
140	};
141	
142	const runStep = (step: Step, customer: Customer): StepResult => {
143	  if (step.op === "quote") return quote(step, customer);
144	
145	  throw new Error(`unsupported step: ${step.op}`);
146	};
147	
148	export const runScenario = (scenario: Scenario): ScenarioResult => ({
149	  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
150	});
