const itemSurchargeOf = (items: Item[], { appliesTo, rate }: ItemSurcharge): number =>
  items
    .filter(appliesTo)
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);

// Item-specific modifiers apply to the affected item's own base premium.
const itemModifiersOf = (items: Item[]): number =>
  ITEM_SURCHARGES.reduce(
    (sum, surcharge) => sum + itemSurchargeOf(items, surcharge),
    0,
  );

const LOYALTY_DISCOUNT_RATE = -0.2;

const LOYALTY_YEARS_THRESHOLD = 2;

// A policy modifier hits the whole policy when the predicate accepts it,
// charging its rate against the policy base premium. Discounts are negative
// rates, so surcharges and discounts sum uniformly.
interface PolicyModifier {
  appliesTo: (customer: Customer) => boolean;
  rate: number;
}

const POLICY_MODIFIERS: PolicyModifier[] = [
  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
  {
    appliesTo: (customer) => customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
    rate: LOYALTY_DISCOUNT_RATE,
  },
];

// Policy-wide modifiers apply to the policy base premium, so they are computed
// from the base alone — item-specific modifiers are not part of their base.
const policyModifiersOf = (policyBase: number, customer: Customer): number =>
  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(customer)).reduce(
    (sum, { rate }) => sum + policyBase * rate,
    0,
  );
